50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	};
61	
62	const BLOCK_SIZE = 3;
63	
64	const BLOCK_BASE_PREMIUM = 60;
65	
66	const countByType = (items: Item[]): Map<string, number> => {
67	  const counts = new Map<string, number>();
68	
69	  for (const item of items) {
70	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
71	  }
72	
73	  return counts;
74	};
75	
76	const groupBasePremiumOf = (type: string, count: number): number =>
77	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
78	
79	const policyBasePremiumOf = (items: Item[]): number =>
80	  [...countByType(items)].reduce(
81	    (sum, [type, count]) => sum + groupBasePremiumOf(type, count),
82	    0,
83	  );
84	
85	const quote = ({ items }: QuoteStep): QuoteResult => {
86	  const policyBase = policyBasePremiumOf(items);
87	
88	  const premiumBeforeRounding =
89	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE;
90	
91	  return { premium: Math.ceil(premiumBeforeRounding) };
92	};
93	
94	const runStep = (step: Step): StepResult => {
95	  if (step.op === "quote") return quote(step);
96	
97	  throw new Error(`unsupported step: ${step.op}`);
98	};
99	
100	export const runScenario = (scenario: Scenario): ScenarioResult => ({
101	  results: scenario.steps.map(runStep),
102	});
